// a tabbed form is the layout that lets it: Tab switches section, ↑↓ moves
// between fields, ←→ cycles a closed set, Space toggles.
func (m Model) handleKey(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	switch msg.String() {
	case "tab":
		return m.switchTab(1)
	case "shift+tab":
		return m.switchTab(-1)
	case "up":
		return m.moveField(-1)
	case "down":
		return m.moveField(1)
	case "left":
		return m.cycleField(-1)
	case "right":
		return m.cycleField(1)
	case keymap.Space:
		return m.toggleField()
	case "enter":
		if m.current().path {
			return m.requestPick()
		}
	case "esc":
		return m.commitField()
	case "ctrl+r":
		return m.requestDetection()
	case keymap.Copy:
		// A letter, so a focused text field keeps it: it falls through to the
		// input below rather than copying anything.
		if !m.current().takesText() {
			return m.copyConnectCommand()
		}
	}

	// Anything else belongs to the input when a text field has focus. Nothing
	// below this point may claim a printable key: a path or a URL can contain
	// any of them.
	if m.current().takesText() {
		var cmd tea.Cmd
		m.input, cmd = m.input.Update(msg)
		return m, cmd
	}
	return m, nil
}

// handlePaste gives pasted text to the focused text field. A modal, or a field
// that takes no text, drops it: a paste is never read as keys (Rule 111).
func (m Model) handlePaste(msg tea.PasteMsg) (tea.Model, tea.Cmd) {
	if m.confirmModal != nil || !m.current().takesText() {
		return m, nil
	}
	var cmd tea.Cmd
	m.input, cmd = m.input.Update(msg)
	return m, cmd
}

	// the lists are simply refetched from the other engine.
	if f.Label == containerEngineLabel {
		if *f.str(m.config) == m.engineOnFocus {
			return m, nil, true
		}
		m.engineOnFocus = *f.str(m.config)
		return m, m.persist(saved{engineChanged: true}), true
	}

	if !f.takesText() {
		return m, nil, true
	}

	// Compared by accessor, not by label: two tabs could both hold a field
	// called "URL", and pointer identity cannot be wrong about which setting is
	// in front of the cursor.
	isForgeURL := f.str != nil && f.str(m.config) == &m.config.Forge.URL
	before := m.config.Forge.URL

	if err := f.Apply(m.config, m.input.Value()); err != nil {
		log.Printf("ERROR [configuration] %s: %v", f.Label, err)
	}
	return m, m.persist(saved{})
}

// toggleField flips a checkbox. Space is the only key that may (Rule 135).
func (m Model) toggleField() (tea.Model, tea.Cmd) {
	f := m.current()

	// A secret row is shown or hidden, and nothing is written: `space` is the
	// only key that toggles anything in a form (Rule 135), and revealing is a
	// toggle like any other.
	if f.Kind == kindSecret {
		if f.Value(m.config) == "" {
			return m, m.footer.Warn("There is no token — the MCP server is not running for this context")
		}
		m.shown[f.Label] = !m.shown[f.Label]
		return m, nil
	}

	if f.Kind != kindToggle {
		return m, nil
	}
	// A warning either way: nothing failed, the box simply cannot move now,
	// and saying why is the point (Rule 130).
	if reason := m.lockReason(f); reason != "" {
		return m, m.footer.Warn(reason)
	}
	if f.guard != nil {
		if reason := f.guard(m.config, !f.Bool(m.config)); reason != "" {
			return m, m.footer.Warn(reason)
		}
	}
	f.Toggle(m.config)
	return m, m.persist(saved{})
}

	if f.Label == secretBackendLabel {
		m.backendOnFocus = m.config.App.SecretBackend
	}
	if f.Label == forgeLabel {
		m.forgeOnFocus = m.config.Forge.Type
	}
	if f.Label == containerEngineLabel {
		m.engineOnFocus = m.config.App.ContainerEngine
	}

	if !f.takesText() {
		m.input.Blur()
		m.input.SetValue("")
		return
	}
	m.resizeInput()
	m.input.SetValue(f.Value(m.config))
	m.input.CursorEnd()
	m.input.Focus()
}

// Labels the view has to recognise. Comparing on the label keeps the field
// table declarative; these four are the only settings that need special
// handling, and naming them here is what makes that visible.
const (
	themeLabel           = "Theme"
		return f, nil

	case "up":
		f.focusedField = (f.focusedField - 1 + maxField + 1) % (maxField + 1)
		f.updateFocus()
		return f, nil

	case "left":
		if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
			f.networkIdx = (f.networkIdx - 1 + len(f.networks)) % len(f.networks)
			return f, nil
		}
	case "right":
		if f.focusedField == f.fieldNetwork() && len(f.networks) > 0 {
			f.networkIdx = (f.networkIdx + 1) % len(f.networks)
			return f, nil
		}

	case keymap.Space:
		// Space toggles checkboxes (Rule 135): port fields and option checkboxes
		if f.isPortField(f.focusedField) {
			f.ports[f.focusedField-f.firstPortField()].enabled = !f.ports[f.focusedField-f.firstPortField()].enabled
			return f, nil
		}
		return f.handleSpaceKey()

	case "enter":
		// Enter advances to next field or submits; never toggles (Rule 135)
		return f.handleEnterKey()
	}

	return f.updateActiveInput(msg)
}

// handleEnterKey processes Enter: advances to next field or submits (Rule 135 — never toggles).
func (f *LaunchForm) handleEnterKey() (*LaunchForm, tea.Cmd) {
	maxField := f.fieldSubmit()
	if f.focusedField == maxField {
		return f.submit()
	}
	f.focusedField = (f.focusedField + 1) % (maxField + 1)
	f.updateFocus()
	return f, nil
}

// handleSpaceKey processes Space: toggles option checkboxes (Rule 135).
func (f *LaunchForm) handleSpaceKey() (*LaunchForm, tea.Cmd) {
	if f.focusedField == f.fieldOptionRemove() {
		f.optionRemove = !f.optionRemove
		return f, nil
	}
	if f.focusedField == f.fieldOptionDetach() {
		f.optionDetach = !f.optionDetach
		if f.optionDetach {
			f.optionInteractiveTTY = false
		}
		return f, nil
	}
	if f.focusedField == f.fieldOptionInteractive() {
		f.optionInteractiveTTY = !f.optionInteractiveTTY
		if f.optionInteractiveTTY {
			f.optionDetach = false
		}
		return f, nil
	}
	return f, nil
}

// handleVerifyFinished updates the verify state, discarding stale results
func (f *LaunchForm) handleVerifyFinished(msg EntrypointVerifyFinishedMsg) (*LaunchForm, tea.Cmd) {
	if msg.Seq != f.verifySeq {
		return f, nil // stale result from a previous entrypoint value
	}
	if msg.OK {
		f.verify = verifyOK
	} else {
		f.verify = verifyWarning
	}
	return f, nil
}

