package configuration

import (
	"testing"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-266: Space reaches a focused text field (a path or a command can
// hold one), and still toggles when the focus is on a checkbox.
func TestSpaceIsInsertedInTheFocusedTextField(t *testing.T) {
	for _, label := range []string{"IDE command", "Terminal command", "Workspaces dir"} {
		t.Run(label, func(t *testing.T) {
			m := focusOn(t, newModel(t), label)
			if !m.current().takesText() {
				t.Fatalf("%q is not a text field", label)
			}
			m.input.SetValue("")

			m = feed(t, m, testutil.Type("a")[0], testutil.Key("space"), testutil.Type("b")[0])

			if got := m.input.Value(); got != "a b" {
				t.Errorf("%s field = %q after typing a, space, b, want %q", label, got, "a b")
			}
		})
	}
}

func TestSpaceStillTogglesACheckbox(t *testing.T) {
	t.Setenv("HOME", t.TempDir())
	t.Setenv("USERPROFILE", t.TempDir())
	m := focusOn(t, newModel(t), "Show hidden files")
	f := m.current()
	if f.Kind != kindToggle {
		t.Fatalf("Show hidden files is not a toggle")
	}
	before := f.Bool(m.config)

	m = feed(t, m, testutil.Key("space"))

	if got := f.Bool(m.config); got == before {
		t.Errorf("space left the checkbox at %v, want it flipped", before)
	}
}
package ociresources

import (
	"testing"

	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// DEVDESK-266: Space reaches the launch form's text fields, so an entrypoint
// like `sh -c "..."` or a volume path with a blank can be typed.
func TestLaunchFormSpaceIsInsertedInEachTextField(t *testing.T) {
	tests := []struct {
		name  string
		field func(f *LaunchForm) int
		value func(f *LaunchForm) string
	}{
		{"entrypoint", (*LaunchForm).fieldEntrypoint, func(f *LaunchForm) string { return f.entrypointInput.Value() }},
		{"env", (*LaunchForm).fieldEnv, func(f *LaunchForm) string { return f.envInput.Value() }},
		{"volumes", (*LaunchForm).fieldVolumes, func(f *LaunchForm) string { return f.volInput.Value() }},
		{"user", (*LaunchForm).fieldUser, func(f *LaunchForm) string { return f.userInput.Value() }},
		{"extra ports", (*LaunchForm).fieldExtraPorts, func(f *LaunchForm) string { return f.extraPortsInput.Value() }},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			f := newKeysForm()
			focusLaunchField(f, tc.field(f))

			f, _ = f.Update(testutil.Type("a")[0])
			f, _ = f.Update(testutil.Key("space"))
			f, _ = f.Update(testutil.Type("b")[0])

			if got := tc.value(f); got != "a b" {
				t.Errorf("%s = %q after typing a, space, b, want %q", tc.name, got, "a b")
			}
		})
	}
}

